	private static void assertIndexedRows(String text, Map<String, Value> parameters, boolean configureIndex,
			boolean verifyRebinding, BiConsumer<TupleFunctionEvaluationMode, List<BindingSet>> assertions)
			throws IOException {
		for (var mode : List.of(TupleFunctionEvaluationMode.TRIPLE_SOURCE, TupleFunctionEvaluationMode.NATIVE,
				TupleFunctionEvaluationMode.SERVICE)) {
			var sail = new LuceneSail();
			sail.setLuceneIndex(new LuceneIndex(new ByteBuffersDirectory(), new StandardAnalyzer()));
			sail.setEvaluationMode(mode);
			if (configureIndex) {
				sail.setParameter(LuceneSail.INDEX_ID, INDEX.stringValue());
			}
			sail.setBaseSail(new MemoryStore());
			var repository = new SailRepository(sail);
			try {
				repository.init();
				try (var connection = repository.getConnection()) {
					connection.begin();
					connection.add(FIRST, FIRST_PROPERTY, VF.createLiteral("green"));
					connection.add(SECOND, SECOND_PROPERTY, VF.createLiteral("green"));
					connection.commit();
					var query = connection.prepareTupleQuery(PREFIX + text);
					parameters.forEach(query::setBinding);
					try (var result = query.evaluate()) {
						assertions.accept(mode, QueryResults.asList(result));
					}
					if (verifyRebinding && parameters.containsKey("q")) {
						query.setBinding("q", VF.createLiteral("absentterm"));
						try (var result = query.evaluate()) {
							assertThat(result.hasNext())
									.as("new API value must control the next evaluation, mode=%s", mode)
									.isFalse();
						}
						query.setBinding("q", parameters.get("q"));
						try (var result = query.evaluate()) {
							assertions.accept(mode, QueryResults.asList(result));
						}
					}
				}
			} finally {
				repository.shutDown();
			}
		}
	}
